"""Fixed drawing skills for local game agents. No room state or model access.

Artists use bundled vector illustrations. Guessers compare only visible public
ink against those illustrations; the secret prompt is never an input.
"""
from functools import lru_cache
import math


def _line(*points):
    return [[round(x / 1000, 4), round(y / 625, 4)] for x, y in points]


def _ellipse(x, y, rx, ry=None, start=0, end=360):
    ry = rx if ry is None else ry
    count = max(3, int(abs(end - start) / 10))
    return _line(*[(x + rx * math.cos(math.radians(start + (end - start) * i / count)),
                   y + ry * math.sin(math.radians(start + (end - start) * i / count))) for i in range(count + 1)])


def _box(x, y, w, h):
    return _line((x, y), (x + w, y), (x + w, y + h), (x, y + h), (x, y))


def _star(x, y, radius=60):
    return _line(*[(x + (radius if i % 2 == 0 else radius * .42) * math.cos(-math.pi / 2 + i * math.pi / 5),
                   y + (radius if i % 2 == 0 else radius * .42) * math.sin(-math.pi / 2 + i * math.pi / 5)) for i in range(11)])


def _rays(x, y, inner, outer, count=10):
    return [_line((x + inner * math.cos(i * 2 * math.pi / count), y + inner * math.sin(i * 2 * math.pi / count)),
                  (x + outer * math.cos(i * 2 * math.pi / count), y + outer * math.sin(i * 2 * math.pi / count))) for i in range(count)]


