_TEMPLATES = _templates()
SUPPORTED_PROMPTS = tuple(_TEMPLATES)


def drawing_for(prompt):
    """Return fresh, bounded canonical strokes for this artist's own prompt."""
    return [{'color': '#244b50', 'width': 5, 'points': [point[:] for point in points]} for points in _TEMPLATES.get(prompt, ())]


_GRID = 32
_MASK = (1 << (_GRID * _GRID)) - 1
_LEFT = sum(1 << (row * _GRID) for row in range(_GRID))
_RIGHT = _LEFT << (_GRID - 1)


def _signature(strokes):
    if not isinstance(strokes, (list, tuple)) or len(strokes) > 384:
        return 0
    lines, points = [], []
    for stroke in strokes:
        if not isinstance(stroke, dict):
            return 0
        color = stroke.get('color', '')
        if not isinstance(color, str):
            return 0
        if color.lower() == '#ffffff':
            continue
        line = stroke.get('points')
        if not isinstance(line, (list, tuple)) or not 1 <= len(line) <= 120:
            return 0
        clean = []
        for point in line:
            if not isinstance(point, (list, tuple)) or len(point) != 2 or any(type(v) not in (int, float) or not 0 <= v <= 1 or not math.isfinite(v) for v in point):
                return 0
            clean.append(point)
        lines.append(clean); points.extend(clean)
        if len(points) > 8000:
            return 0
    if len(points) < 3:
        return 0
    left, right = min(p[0] for p in points), max(p[0] for p in points)
    top, bottom = min(p[1] for p in points), max(p[1] for p in points)
    scale = max(right - left, bottom - top)
    if scale < .025:
        return 0
    def grid(point):
        return (round(2 + ((point[0] - left) / scale + (1 - (right - left) / scale) / 2) * 27),
                round(2 + ((point[1] - top) / scale + (1 - (bottom - top) / scale) / 2) * 27))
    bits, edges = 0, set()
    for line in lines:
        prior = grid(line[0])
        bits |= 1 << (prior[1] * _GRID + prior[0])
        for point in line[1:]:
            current = grid(point)
            edge = tuple(sorted((prior, current)))
            if current == prior or edge in edges:
                prior = current
                continue
            edges.add(edge)
            steps = max(abs(current[0] - prior[0]), abs(current[1] - prior[1]), 1)
            for step in range(1, steps + 1):
                x = round(prior[0] + (current[0] - prior[0]) * step / steps)
                y = round(prior[1] + (current[1] - prior[1]) * step / steps)
                bits |= 1 << (y * _GRID + x)
            if bits.bit_count() > 750:
                return 0
            prior = current
    return bits


def _spread(bits):
    horizontal = bits | ((bits & ~_LEFT) >> 1) | ((bits & ~_RIGHT) << 1)
    return (horizontal | horizontal << _GRID | horizontal >> _GRID) & _MASK


@lru_cache(maxsize=1)
def _vocabulary():
    return tuple((prompt, signature, _spread(signature)) for prompt in SUPPORTED_PROMPTS for signature in [_signature(drawing_for(prompt))])


def rank_guesses(strokes):
    """Rank public ink only. Empty/invalid/tiny ink yields no invented answer."""
    signature = _signature(strokes)
    if not signature or signature.bit_count() < 10:
        return []
    spread, count = _spread(signature), signature.bit_count()
    scores = []
    for prompt, reference, reference_spread in _vocabulary():
        coverage = (signature & reference_spread).bit_count() / count
        completeness = (reference & spread).bit_count() / max(reference.bit_count(), 1)
        score = 2 * coverage * completeness / max(coverage + completeness, .001)
        scores.append((score, prompt))
    scores.sort(key=lambda item: (-item[0], item[1]))
    # Partial doodles remain uncertain; the agent may pass instead of pretending
    # to understand every possible freehand illustration.
    return [prompt for score, prompt in scores[:3] if score >= .48]
